final class OpenDrawerTests: XCTestCase {
    func testOpenDrawer() {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        Thread.sleep(forTimeInterval: 2)
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let point = springboard.coordinate(withNormalizedOffset: CGVector(dx: 0.074, dy: 0.046))
        point.tap()
        Thread.sleep(forTimeInterval: 3)
    }
